Section TailStmts.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.

  (* [comment removed for export] *)
  Definition atail_usage_stmt : Prop :=
    forall (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
           (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z)
           (s : as_St H) (msF : machine_state) (mo : Model) (regs : bvmap 5 word) (mem : word -> option byte),
      valid_argv argv -> AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can -> length argv <> 2%nat ->
      as_VIS H s msF = mkst regs (Z_to_bv 64 0xa2e68) mem (seg_rom asegs) -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x65d4b0 -> getr regs 8 = Z_to_bv 64 2 ->
      getr regs 10 = Z_to_bv 64 (Z.of_nat (length argv)) -> getr regs 11 = Z_to_bv 64 (bv_unsigned sp0 + 8) ->
      mstatics H sp0 tid can mem0 mem ->
      m_fds mo = m_fds mo0 ->
      m_channel_reader mo = true ->
      realizes asegs (mkCfg msF mo) (t_die (msg_usage (hd [] argv)) (m_fs mo)).

  (* [comment removed for export] *)
  Definition atail_open_stmt : Prop :=
    forall (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
           (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z) (a0s path : list byte) (pp : Z)
           (s : as_St H) (msF : machine_state) (mo : Model) (regs : bvmap 5 word) (mem : word -> option byte),
      valid_argv argv -> AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can -> argv = [a0s; path] ->
      rdn RSEGS mem0 (Z_to_bv 64 (bv_unsigned sp0 + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 pp)) -> astr_at mem0 sp0 pp path ->
      as_VIS H s msF = mkst regs (Z_to_bv 64 0xa2f60) mem (seg_rom asegs) -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x65d4b0 -> getr regs 18 = Z_to_bv 64 pp ->
      mstatics H sp0 tid can mem0 mem ->
      fd_lookup (m_fds mo) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)) ->
      m_channel_reader mo = true ->
      realizes asegs (mkCfg msF mo) (t_die (msg_cannot_open path) (m_fs mo)).

  (* [comment removed for export] *)
  Definition atail_rderr_stmt : Prop :=
    forall (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
           (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z) (a0s path : list byte) (pp : Z)
           (s : as_St H) (msF : machine_state) (mo : Model) (regs : bvmap 5 word) (mem : word -> option byte),
      valid_argv argv -> AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can -> argv = [a0s; path] ->
      rdn RSEGS mem0 (Z_to_bv 64 (bv_unsigned sp0 + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 pp)) -> astr_at mem0 sp0 pp path ->
      as_VIS H s msF = mkst regs (Z_to_bv 64 0xa2efc) mem (seg_rom asegs) -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x65d4b0 -> getr regs 18 = Z_to_bv 64 pp ->
      mstatics H sp0 tid can mem0 mem ->
      fd_lookup (m_fds mo) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)) ->
      m_channel_reader mo = true ->
      realizes asegs (mkCfg msF mo) (t_die (msg_read_error path) (m_fs mo)).
End TailStmts.

Section ATop.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis DL : asan_driver_laws H.
  Hypothesis TR : as_target_run_stmt H.
  Hypothesis LIVE : ADRV_LIVE <= as_LIVE_MAX H /\ ADRV_CNT <= as_LIVE_CNT_MAX H.
  Hypothesis TUS : atail_usage_stmt H.
  Hypothesis TOP : atail_open_stmt H.
  Hypothesis TRD : atail_rderr_stmt H.
  Variables (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
            (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z).
  Hypothesis Hva : valid_argv argv.
  Hypothesis PRE : AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can.
  (* The model's channel reader at main (As/AsMainPre.v:99), which every write to fd 1/2 needs
     (As/AsDrvIO.v:57,102,122).  Every model below gets it from here through
     same_but_materialized_reader (As/LazyRestrict.v:852), adl_rdr (As/AsDriverLaws.v:44) and the
     reader equations of the continuations of As/AsMainLoop.v and As/AsDrvRead.v. *)
  Hypothesis RDR : m_channel_reader mo0 = true.

  Let rom := seg_rom asegs.
  Let Hvsp : valid_sp sp0. Proof. exact (am_vsp _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
  Let HCE : hceil + 8388608 <= bv_unsigned sp0. Proof. exact (am_ceil _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
  Let Htid : 0 < tid < 2 ^ 22. Proof. exact (proj2 (am_tid _ _ _ _ _ _ _ _ _ _ _ PRE)). Qed.
  Let TRC : adrv_traces H. Proof. exact (am_tr _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
  Let SPlo : 0x7fff80000000 <= bv_unsigned sp0. Proof. exact (proj1 Hvsp). Qed.
  Let SPhi : bv_unsigned sp0 <= 0x800000000000. Proof. exact (proj1 (proj2 Hvsp)). Qed.
  Let SP16 : bv_unsigned sp0 mod 16 = 0. Proof. exact (proj2 (proj2 Hvsp)). Qed.
  Let lo : Z := bv_unsigned sp0 - 128 - ATR_STACK.
  Let Elo : lo = bv_unsigned sp0 - 128 - 65536. Proof. reflexivity. Qed.
  Let COSTS : cost_laws H. Proof. exact (ah_costs H HH). Qed.

  Lemma aceil_loT : aceil + 4096 <= lo.
  Proof. pose proof Elo. pose proof HCE. acb. lia. Qed.
