    (* [comment removed for export] *)
    Lemma abuf_bytes_of_rdn : forall m (A : Z) (data : list byte),
      rdn RSEGS m (Z_to_bv 64 A) (length data) = Some data -> 0 <= A -> A + Z.of_nat (length data) < 2 ^ 64 -> abuf_bytes m A data.
    Proof.
      intros m A data HD HA HAn i Hi. pose proof (rdn_nth RSEGS m (length data) (Z_to_bv 64 A) data i HD Hi) as R.
      unfold nat_to_word in R. rewrite Z_to_bv_89590 in R. exact R.
    Qed.

    Section File.
      Variable data : list byte.
      Hypothesis Hdata : fs_lookup (m_fs mo0) path = Some data.

      (* [comment removed for export] *)
      Lemma after_tr : forall A cap p s mo regs mem regs2 mem2 msF2 mo2 s2 k,
        mstatics H sp0 tid can mem0 mem ->
        ATRpost H (Z_to_bv 64 (bv_unsigned sp0 - 128)) A cap data p s [(p, A, cap)] mo regs mem regs2 mem2 msF2 mo2 s2 ->
        m_channel_reader mo = true ->
        getr regs 9 = Z_to_bv 64 A ->
        0 <= k <= 10 -> aleft H k <= as_AL H s -> Z.of_nat (length data) < MAX_INPUT -> 6 + hdr_cfg data <= Z.of_nat (length data) ->
        0 <= cap <= 2 ^ 26 ->
        realizes asegs (mkCfg msF2 mo2) (t_emit (W 1 (zero_lines (Nat.pred (hdr_calls data)))) (t_exit (exit_code 0) (m_fs mo))).
      (* Text proof: free_exit (As/AsMainExit.v:166) now takes the channel reader after its
         fd_lookup premise (:174).  Ported from the text [after_tr] of spirv-tools/
         spvtools_binary_parser_fuzzer bpA/Drv/AsMainTop.v and openssl/echconfiglist_parser
         As/AsMainTop.v, on the lemmas the recorded body named; this unit's ATRpost
         (As/AsDrvDefs.v:223-253) has the atexit-table and latch fields, and its pcs are 0xa2e44
         (As/AsDrvDefs.v:226) and 0xa2ec4 (As/AsMainRet.v:28).  The reader at the exit model comes
         from the target run's as_MPRES (adl_rdr) and the SB step of the return.  [Proof using]
         is the former body's dependency set plus LIVE and RDR, which TR_of_aleft's lia may pull in
         (see first_alloc); used only inside the Section. *)
      Proof using HCEIL H HH DL LIVE sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE RDR data rom Hvsp HCE Htid TRC SPlo SPhi SP16 lo Elo COSTS.
        intros A cap p s mo regs mem regs2 mem2 msF2 mo2 s2 k ST PO RD R9 Hk HAL HLT H6 Hcap.
        pose proof SPlo as Hlo. pose proof SPhi as Hhi. pose proof (hdr_calls_range data) as HCR.
        pose proof (xstat_after_tr _ _ _ _ _ _ _ _ _ _ _ _ _ _ ST PO) as XS2.
        destruct PO as [HV2 HA2 MP2 Q2 Q4 Q10 QCS QAB QSTK QSTKC [LB' [RH' PERM]] QAL QAUX QDATA QADDR [junk QCB] QST QAXT QLAT QOUT QFS QFD1 QFD2].
        rewrite (Permutation_single _ _ PERM) in RH'.
        destruct (amain_ret_0 regs2 mem2 (seg_rom asegs) Q10) as (regs3 & RUN & E8 & E10 & KEEP).
        lazymatch type of RUN with _ _ (mkst _ ?pc _ _) (mkst _ ?pc' _ _) =>
          replace (Z_to_bv 64 0xa2e44) with pc in HV2 by (apply bv_eq; reflexivity) end.
        eapply (drv_msteps H DL s2 msF2 regs2 _ mem2 regs3 _ mem2 mo2 _ HV2 HA2 RUN).
        intros msF3 mo3 HV3 HA3 SB3.
        lazymatch type of HV3 with _ = mkst _ ?pc' _ _ => replace pc' with (Z_to_bv 64 0xa2ec4) in HV3 by (apply bv_eq; reflexivity) end.
        assert (NE : forall r : reg, In r [2; 4; 9]%bv -> r <> 1%bv /\ r <> 8%bv /\ r <> 10%bv /\ r <> 11%bv).
        { intros r Hr. cbn [In] in Hr. destruct Hr as [<-|[<-|[<-|[]]]]; repeat split; intros E; apply (f_equal bv_unsigned) in E; discriminate. }
        assert (K2 : getr regs3 2 = Z_to_bv 64 (bv_unsigned sp0 - 128)).
        { destruct (NE 2%bv ltac:(in_solve)) as (N1 & N2 & N3 & N4). rewrite (KEEP _ N1 N2 N3 N4). exact Q2. }
        assert (K4 : getr regs3 4 = Z_to_bv 64 ATP).
        { destruct (NE 4%bv ltac:(in_solve)) as (N1 & N2 & N3 & N4). rewrite (KEEP _ N1 N2 N3 N4). exact Q4. }
        assert (K9 : getr regs3 9 = Z_to_bv 64 A).
        { destruct (NE 9%bv ltac:(in_solve)) as (N1 & N2 & N3 & N4). rewrite (KEEP _ N1 N2 N3 N4), (QCS 9%bv ltac:(in_solve)). exact R9. }
        rewrite <- QFS, <- (same_but_materialized_fs _ _ SB3). rewrite <- (exit_code_and_255 0) by lia. unfold exit_code. rewrite <- E8.
        eapply (free_exit H HH DL sp0 Hvsp HCE TRC true s2 msF3 mo3 regs3 mem2 p A cap (getr regs3 8) _ junk HV3 HA3 K2 K4 eq_refl K9);
          [ rewrite E8, u_small by lia; lia | exact RH' | exact QCB | exact QADDR
          | destruct (TR_of_aleft k (as_AL H s) data Hk HAL HLT H6) as [_ X]; apply (X _ cap QAL); lia
          | exact XS2
          | right; exists (Nat.pred (hdr_calls data)); split; [lia|]; split; [exact QOUT | reflexivity]
          | intros _; reflexivity
          | rewrite (same_but_materialized_fds _ _ SB3); exact QFD1
          | rewrite (same_but_materialized_reader _ _ SB3), (adl_rdr H DL _ _ MP2); exact RD ].
      Qed.

