      (* [comment removed for export] *)
      Theorem as_file :
        (length path <= 4095)%nat -> path <> [] -> path_has_slash path = false -> path_is_dirref path = false ->
        realizes asegs (mkCfg msF0 mo0) (t_alt2 (t_die (msg_cannot_open path) (m_fs mo0)) (t_opened data (m_fs mo0))).
      (* Text proof: the open-error tail TOP, first_alloc, loop_sound, close_step (As/AsMainLoop.v),
         x_header and refuse_exit (As/AsMainExit.v:264) carry the channel reader, so the recorded
         body no longer fits.  Ported from the text [as_file] of spirv-tools/
         spvtools_binary_parser_fuzzer bpA/Drv/AsMainTop.v and openssl/echconfiglist_parser
         As/AsMainTop.v, on the lemmas the recorded body named; the constants are this unit's: the
         openat pc 0x10e4e0 and its successor 0x10e4e4 (As/AsMainOpen.v:136,194), the malloc stub
         0x73278 = AMALLOC_STUB (As/AsMainOpen.v:181, As/AsIface.v:25).  The reader is RDR carried
         along every model: aseg_A's, openat's, aseg_F's/aseg_C's SB steps, then the reader
         equations of first_alloc, loop_sound and close_step.  [Proof using] is the former body's
         dependency set plus RDR. *)
      Proof using HCEIL H HH DL TR LIVE TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can Hva PRE RDR a0s path Hargv p0 pp Hp0 Hpp data Hdata rom Hvsp HCE Htid TRC SPlo SPhi SP16 lo Elo COSTS ppw E0.
        intros Hlen Hne Hsl Hnd. pose proof SPlo as Hlo. pose proof SPhi as Hhi. pose proof Elo. pose proof aceil_loT as HCL. acb.
        pose proof (eq_refl : ATR_STACK = 65536) as EATR.
        pose proof (am_fds _ _ _ _ _ _ _ _ _ _ _ PRE) as FDS0.
        apply (aseg_A H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE a0s path Hargv p0 pp Hp0 Hpp).
        intros R M msF mo HV HA SB HR HK FM FA.
        pose proof (amst_at_open M FM FA) as ST. pose proof (arh_at_open M FM) as RH.
        assert (STKM : stk asegs M lo (bv_unsigned sp0 - 128))
          by (destruct (mst_stk H sp0 tid can mem0 _ ST) as (S1 & S2 & S3); split; [exact S1 | split; [lia | intros a Ha; apply S3; lia]]).
        destruct (aopenat_regs sp0 regs0 tid can p0 pp R HR) as (H17 & H10 & H11 & Hfl).
        pose proof (apath_at_A H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE path p0 pp Hpp M R FM HR Hlen) as PA.
        destruct (mo_sb _ _ SB) as [EFS EFDS].
        assert (RDm : m_channel_reader mo = true) by (rewrite (same_but_materialized_reader _ _ SB); exact RDR).
        assert (Hfree : fd_lookup (m_fds mo) (alloc_fd (m_fds mo)) = None) by (rewrite EFDS, FDS0; reflexivity).
        unfold t_opened. rewrite <- EFS.
        eapply (drv_openat_file H DL s0 msF R (Z_to_bv 64 0x10e4e0) M mo ECALLW AECALL2 is_ecall_ECALLW HV HA H17 H10 Hfl Hfree path data);
          [ exact PA | exact Hne | exact Hsl | exact Hnd | rewrite EFS; exact Hdata | |].
        - (* openat fails: the cannot-open tail *)
          intros e msF' mo' He HV' HA' SB'. rewrite AgentLib.v_addi_lit in HV' by lia. change (0x10e4e0 + 4)%Z with 0x10e4e4%Z in HV'.
          eapply (aseg_F H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE p0 pp e R M msF' mo' _ HV' HA' (openat_errnos_range e He) (scF_openat e He) HR HK).
          intros R' M' msF2 mo2 HV2 HA2 SB2 Q2 Q4 Q8 Q18 FM2.
          rewrite <- (same_but_materialized_fs _ _ SB'), <- (same_but_materialized_fs _ _ SB2).
          eapply (TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can a0s path pp s0 msF2 mo2 R' M' Hva PRE Hargv (proj1 Hpp) (proj2 Hpp) HV2 HA2 Q2 Q4 Q18).
          + pose proof (frame_mod_munch _ _ _ FM2) as MU2. unfold aregF_w, ivls in MU2. cbn [map fst snd] in MU2. rewrite !u_small in MU2 by lia.
            eapply (mstatics_munch H HH sp0 tid can mem0 Hvsp HCE M M' _ [] ST MU2 (aframe_mod_wmono _ _ _ FM2)).
            * constructor; [left; cbn [fst snd]; lia | constructor; [right; left; reflexivity | constructor]].
            * eapply amem_inv_frame; [exact (mst_inv H sp0 tid can mem0 _ ST) | exact FM2 |].
              unfold aregF_w. constructor; [| constructor; [|constructor]]; cbn [fst snd]; rewrite u_small by lia; lia.
            * apply (astk_grows M M'); [exact STKM | lia | lia | exact (proj2 FM2)].
            * eapply ACONST_frame; [exact (mst_ac H sp0 tid can mem0 _ ST) | exact MU2 | exact (aframe_mod_wmono _ _ _ FM2) |].
              constructor; [apply aconst_ok_hi; cbn [fst]; unfold AHI_LO; lia | constructor; [exact aconst_ok_errno | constructor]].
          + rewrite (same_but_materialized_fds _ _ SB2), (same_but_materialized_fds _ _ SB'), EFDS, FDS0. reflexivity.
          + rewrite (same_but_materialized_reader _ _ SB2), (same_but_materialized_reader _ _ SB'). exact RDm.
        - (* openat succeeds with fd 3: malloc, the read loop, close, then the header *)
          intros msF' mo' HV' HA' SB'. rewrite AgentLib.v_addi_lit in HV' by lia. change (0x10e4e0 + 4)%Z with 0x10e4e4%Z in HV'.
          replace (alloc_fd (m_fds mo)) with (Z_to_bv 64 3) in HV', SB' by (rewrite EFDS, FDS0; reflexivity).
          assert (RD' : m_channel_reader mo' = true) by (rewrite (same_but_materialized_reader _ _ SB'); exact RDm).
          eapply (aseg_C H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE p0 pp R M msF' mo' _ HV' HA' HR HK).
          intros R' msF2 mo2 HV2 HA2 SB2 Q1 Q2 Q4 Q8 Q10 Q18 Q20 Q21.
          change (Z_to_bv 64 0x73278) with (Z_to_bv 64 AMALLOC_STUB) in HV2.
          assert (RD2 : m_channel_reader mo2 = true) by (rewrite (same_but_materialized_reader _ _ SB2); exact RD').
          eapply (first_alloc R' M msF2 mo2 _ HV2 HA2 Q1 Q2 Q4 Q8 Q10 Q18 Q20 Q21 ST RH (am_al _ _ _ _ _ _ _ _ _ _ _ PRE)).
          intros regs3 mem3 msF3 mo3 A p s HV3 HA3 RC RH3 CB3 AD3 ST3 HAL3 FS3 FDS3 RD3.
          eapply (loop_sound H HH DL sp0 pp tid can path data (m_fs mo) mem0 Hvsp HCE ltac:(rewrite EFS; exact Hdata) Htid TRC LIVE
                    (length data) 0 65536 A s p regs3 mem3 msF3 mo3).
          + lia.
          + exact HV3.
          + exact HA3.
          + eapply (ARInv0 data (m_fs mo) mo2); try eassumption.
            * rewrite (same_but_materialized_fs _ _ SB2), (same_but_materialized_fs _ _ SB'). reflexivity.
            * rewrite (same_but_materialized_fds _ _ SB2), (same_but_materialized_fds _ _ SB'), with_fds_fds, EFDS. reflexivity.
          + intros cap' A' s' p' regs4 mem4 msF4 mo4 HV4 HA4 CI RD4.
            eapply (close_step H DL sp0 pp tid can data (m_fs mo) mem0); [exact HV4 | exact HA4 | exact CI |].
            intros regs5 msF5 mo5 HV5 HA5 XI RD5. rewrite EFS.
            eapply x_header; [exact HV5 | exact HA5 | rewrite <- EFS; exact XI |].
            rewrite RD5, RD4, RD3. exact RD2.
          + intros Hbig A' s' p' regs4 mem4 msF4 mo4 HV4 HA4 RF RD4.
            unfold t_body. cbv zeta. replace (MAX_INPUT <=? Z.of_nat (length data))%Z with true by (symmetry; apply Z.leb_le; lia).
            eapply (refuse_exit H DL sp0 tid can Hvsp HCE Htid mem0 pp); [exact HV4 | exact HA4 | exact RF |].
            rewrite RD4, RD3. exact RD2.
      Qed.
    End File.

