    Lemma open_fail : forall e R M msF' mo',
      In e openat_errnos \/ e = ENAMETOOLONG \/ e = ENOENT ->
      regs_ok E0 srA R -> know_ok RSEGS E0 M knA -> mstatics H sp0 tid can mem0 M ->
      as_VIS H s0 msF' = mkst (regupd R 10 (errno_ret e)) (Z_to_bv 64 0x10e4e4) M rom -> as_AKREL H s0 (mkCfg msF' mo') ->
      m_fds mo' = m_fds mo0 ->
      m_channel_reader mo' = true ->
      realizes asegs (mkCfg msF' mo') (t_die (msg_cannot_open path) (m_fs mo')).
    (* Text proof: the open-error tail TOP takes the channel reader as its last premise, so the
       recorded body no longer fits.  Ported from the text [open_fail] of spirv-tools/
       spvtools_binary_parser_fuzzer bpA/Drv/AsMainTop.v and openssl/echconfiglist_parser
       As/AsMainTop.v, on the lemmas the recorded body named (aseg_F, mstatics_munch, TOP).  The
       reader comes from the new premise through aseg_F's SB step.  [Proof using] is the former
       body's dependency set plus RDR, which aceil_loT may take (see first_alloc); used only inside
       the Section. *)
    Proof using HCEIL H HH DL TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can Hva PRE RDR a0s path Hargv p0 pp Hpp rom Hvsp HCE Htid TRC SPlo SPhi SP16 lo Elo COSTS E0.
      intros e R M msF' mo' He HR HK ST HV' HA' EFDS ERD. pose proof SPlo as Hlo. pose proof SPhi as Hhi. pose proof Elo. pose proof aceil_loT as HCL. acb.
      pose proof (eq_refl : ATR_STACK = 65536) as EATR.
      pose proof (am_fds _ _ _ _ _ _ _ _ _ _ _ PRE) as FDS0.
      assert (STKM : stk asegs M lo (bv_unsigned sp0 - 128))
        by (destruct (mst_stk H sp0 tid can mem0 _ ST) as (S1 & S2 & S3); split; [exact S1 | split; [lia | intros a Ha; apply S3; lia]]).
      assert (HeR : 1 <= e <= 4095 /\ scF e).
      { destruct He as [He|[->| ->]]; [split; [apply openat_errnos_range | apply scF_openat]; exact He
          | split; [unfold ENAMETOOLONG; lia | exact scF_ENAMETOOLONG] | split; [unfold ENOENT; lia | exact scF_ENOENT]]. }
      destruct HeR as [HeR HSC].
      eapply (aseg_F H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE p0 pp e R M msF' mo' _ HV' HA' HeR HSC HR HK).
      intros R' M' msF2 mo2 HV2 HA2 SB2 Q2 Q4 Q8 Q18 FM2.
      rewrite <- (same_but_materialized_fs _ _ SB2).
      eapply (TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can a0s path pp s0 msF2 mo2 R' M' Hva PRE Hargv (proj1 Hpp) (proj2 Hpp) HV2 HA2 Q2 Q4 Q18).
      - pose proof (frame_mod_munch _ _ _ FM2) as MU2. unfold aregF_w, ivls in MU2. cbn [map fst snd] in MU2. rewrite !u_small in MU2 by lia.
        eapply (mstatics_munch H HH sp0 tid can mem0 Hvsp HCE M M' _ [] ST MU2 (aframe_mod_wmono _ _ _ FM2)).
        * constructor; [left; cbn [fst snd]; lia | constructor; [right; left; reflexivity | constructor]].
        * eapply amem_inv_frame; [exact (mst_inv H sp0 tid can mem0 _ ST) | exact FM2 |].
          unfold aregF_w. constructor; [| constructor; [|constructor]]; cbn [fst snd]; rewrite u_small by lia; lia.
        * apply (astk_grows M M'); [exact STKM | lia | lia | exact (proj2 FM2)].
        * eapply ACONST_frame; [exact (mst_ac H sp0 tid can mem0 _ ST) | exact MU2 | exact (aframe_mod_wmono _ _ _ FM2) |].
          constructor; [apply aconst_ok_hi; cbn [fst]; unfold AHI_LO; lia | constructor; [exact aconst_ok_errno | constructor]].
      - rewrite (same_but_materialized_fds _ _ SB2), EFDS, FDS0. reflexivity.
      - rewrite (same_but_materialized_reader _ _ SB2). exact ERD.
    Qed.

