    Theorem as_open_fail_toolong :
      (4096 <= length path)%nat ->
      realizes asegs (mkCfg msF0 mo0) (t_die (msg_cannot_open path) (m_fs mo0)).
    (* [Proof using]: the dependency set of the text below as it stood (the same as
       as_open_fail_absent's), plus RDR, which the open_fail call now takes. *)
    Proof using HCEIL H HH DL TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can Hva PRE RDR a0s path Hargv p0 pp Hp0 Hpp rom Hvsp HCE Htid TRC SPlo SPhi SP16 lo Elo COSTS E0.
      (* LPS 75d69e00: [drv_openat_toolong] now also takes the TASK_SIZE bound on the
         4096-byte read (the model's [cstr_access_len_aux] passes [access_okb] per byte), so
         the recorded proof no longer fits; restated by hand on as_open_fail_absent's text
         below, with the recorded proof's own lemmas (rdn_agree/above_A, rdn_firstn,
         firstn_app, firstn_skipn).  The bound is astr_at's
         `pp + length path + 10 <= 0x800000000000` = TASK_SIZE with 4096 <= length path. *)
      intros Hlong. pose proof SPlo as Hlo. pose proof SPhi as Hhi.
      apply (aseg_A H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE a0s path Hargv p0 pp Hp0 Hpp).
      intros R M msF mo HV HA SB HR HK FM FA.
      pose proof (amst_at_open M FM FA) as ST. destruct (mo_sb _ _ SB) as [EFS EFDS].
      destruct (aopenat_regs sp0 regs0 tid can p0 pp R HR) as (H17 & H10 & H11 & Hfl).
      destruct Hpp as [_ (S1a & S1b & S1c & S1d & S1e)].
      assert (HrdM : rdn asegs M (Z_to_bv 64 pp) (length path + 1) = Some (path ++ [Z_to_bv 8 0])).
      { rewrite <- S1d. apply rdn_agree. intros j Hj.
        apply (above_A H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE M FM). unorm. lia. }
      assert (Hrd : rdn asegs M (getr R 11) 4096 = Some (firstn 4096 path)).
      { rewrite H11, (rdn_firstn _ _ _ _ _ 4096 HrdM) by lia.
        rewrite firstn_app.
        replace (4096 - length path)%nat with 0%nat by lia.
        rewrite firstn_O, app_nil_r. reflexivity. }
      assert (Hnz : ~ In (Z_to_bv 8 0) (firstn 4096 path)).
      { intro Hin. apply S1c. rewrite <- (firstn_skipn 4096 path). apply in_or_app. left. exact Hin. }
      assert (Hts : (bv_unsigned (getr R 11) + 4096 <= TASK_SIZE)%Z).
      { rewrite H11. unfold TASK_SIZE. unorm. lia. }
      eapply (drv_openat_toolong H DL s0 msF R (Z_to_bv 64 0x10e4e0) M mo ECALLW AECALL2 is_ecall_ECALLW HV HA H17 H10 Hfl (firstn 4096 path));
        [exact Hrd | exact Hnz | exact Hts |].
      intros msF' mo' HV' HA' SB'. rewrite AgentLib.v_addi_lit in HV' by lia. change (0x10e4e0 + 4)%Z with 0x10e4e4%Z in HV'.
      rewrite <- EFS, <- (same_but_materialized_fs _ _ SB').
      apply (open_fail ENAMETOOLONG R M msF' mo' ltac:(right; left; reflexivity) HR HK ST HV' HA').
      - rewrite (same_but_materialized_fds _ _ SB'). exact EFDS.
      - rewrite (same_but_materialized_reader _ _ SB'), (same_but_materialized_reader _ _ SB). exact RDR.
    Qed.

